import { and, eq, inArray } from "drizzle-orm";
import { db } from "../db/index.js";
import { activityAnalyses } from "../db/schema.js";

export interface StoredAnalysis {
  activityId: number;
  model: string;
  text: string;
  generatedAt: Date;
}

/**
 * Loads cached analyses for the given activities, limited to the currently
 * selected model and prompt version. An analysis produced by a different model
 * or prompt version is stale and is regenerated by the caller.
 */
export async function loadAnalyses(
  activityIds: number[],
  model: string,
  promptVersion: number,
): Promise<Map<number, StoredAnalysis>> {
  if (activityIds.length === 0) {
    return new Map();
  }

  const rows = await db
    .select()
    .from(activityAnalyses)
    .where(
      and(
        inArray(activityAnalyses.activityId, activityIds),
        eq(activityAnalyses.model, model),
        eq(activityAnalyses.promptVersion, promptVersion),
      ),
    );

  return new Map(
    rows.map((row) => [
      row.activityId,
      {
        activityId: row.activityId,
        model: row.model,
        text: row.analysis,
        generatedAt: row.updatedAt,
      },
    ]),
  );
}

/** Inserts or replaces the cached analysis for one activity. */
export async function saveAnalysis(input: {
  activityId: number;
  model: string;
  promptVersion: number;
  text: string;
}): Promise<StoredAnalysis> {
  const now = new Date();
  const [row] = await db
    .insert(activityAnalyses)
    .values({
      activityId: input.activityId,
      model: input.model,
      promptVersion: input.promptVersion,
      analysis: input.text,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: activityAnalyses.activityId,
      set: {
        model: input.model,
        promptVersion: input.promptVersion,
        analysis: input.text,
        updatedAt: now,
      },
    })
    .returning();

  if (!row) {
    throw new Error("failed to persist activity analysis");
  }
  return {
    activityId: row.activityId,
    model: row.model,
    text: row.analysis,
    generatedAt: row.updatedAt,
  };
}
